/* Ad-free stub replacing the GameDistribution SDK bundle (was ~1MB).
   Keeps the same public API (window.gdsdk / window.gdApi) so the game's
   calls still work, but never loads ads, trackers or network scripts. */
(function () {
  var opts = window.GD_OPTIONS || {};
  function emit(name, status) {
    try { if (typeof opts.onEvent === 'function') opts.onEvent({ name: name, message: name, status: status || 'success' }); } catch (e) {}
  }
  var ok = function () { return Promise.resolve(); };
  var api = {
    showAd: function (type) {
      // Resume the game immediately; grant reward for rewarded ads.
      setTimeout(function () {
        emit('SDK_GAME_PAUSE');
        if (String(type) === 'rewarded') emit('SDK_REWARDED_WATCH_COMPLETE');
        emit('SDK_GAME_START');
      }, 0);
      return Promise.resolve('ad skipped');
    },
    preloadAd: ok, cancelAd: ok, showBanner: ok, showDisplayAd: ok,
    showLeaderBoard: ok, onResumeGame: function () {}, onPauseGame: function () {},
    openConsole: function () {}, clearSession: function () {}, play: function () {}, customLog: function () {}
  };
  window.gdsdk = window.gdApi = api;
  setTimeout(function () { emit('SDK_READY'); emit('SDK_GAME_START'); }, 0);
})();
